from typing import List, Optional, Literal
from pydantic import BaseModel, Field

class OrderSchema(BaseModel):
    """Specification for work order generated by HEAD."""
    goal: str = Field(..., description="The objective of this run")
    reference_paths: List[str] = Field(default_factory=list, description="Explicit absolute read-only document paths supplied for this task")
    required_outputs: List[str] = Field(default_factory=list, description="Exact nonempty project-relative deliverable files, including new behavior tests when requested")
    allowed_paths: List[str] = Field(
        default_factory=list,
        description="Explicitly permitted file or directory paths for modification"
    )
    protected_paths: List[str] = Field(
        default_factory=list,
        description="Explicitly protected file or directory paths that must never be touched"
    )
    acceptance_criteria: List[str] = Field(
        default_factory=list,
        description="List of acceptance criteria that must be satisfied"
    )
    max_files_changed: int = Field(
        default=15,
        description="Maximum number of files permitted to be changed"
    )
    max_diff_lines: int = Field(
        default=800,
        description="Maximum lines of git diff permitted across all changed files"
    )
    allowed_deletions: List[str] = Field(
        default_factory=list,
        description="Explicitly permitted deletions of functions, classes, tests, or files"
    )
    context: Optional[str] = Field(
        default=None,
        description="Optional additional context or architectural instructions"
    )
    risk_level: Literal["LOW", "MEDIUM", "HIGH"] = Field(
        default="LOW",
        description="HEAD's risk assessment of the change; HIGH always requires human approval"
    )
    requires_human_approval: bool = Field(
        default=False,
        description="Explicit HEAD request for human approval before autonomous execution"
    )
